import React, { useState } from 'react';
import { ChevronDown, MoreHorizontal, CheckCircle2, ChevronRight } from 'lucide-react';

const mockFAQs = [
  {
    id: 1,
    title: 'How can I make reservations?',
    content:
      'Visit our reservations section or our in-app chat for live seating. Bookings are confirmed instantly and saved to your profile.',
    isOpen: false,
  },
  {
    id: 2,
    title: 'What are the hours for the wine list?',
    content:
      'Our sommelier-curated wine list is available for tasting and pairing throughout dinner hours. Tastings are complimentary with an order.',
    isOpen: false,
  },
  {
    id: 3,
    title: 'Do you have gluten-free options?',
    content:
      'Yes, we have a dedicated gluten-free pizza crust and a selection of gluten-free pasta dishes. Please inform your server.',
    isOpen: false,
  },
  {
    id: 4,
    title: 'Are there outdoor seating areas?',
    content:
      'Yes, we have a charming outdoor terrace with seating for both dining and cocktail service. Reservations recommended, especially on weekends.',
    isOpen: false,
  },
];

export default function Faq() {
  const [active, setActive] = useState([]);

  const toggle = (id) => {
    if (active.includes(id)) {
      setActive(active.filter((i) => i !== id));
    } else {
      setActive([id]);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 bg-white/5 rounded-2xl shadow-2xl border border-white/10 text-slate-200 font-sans antialiased">
      {/* Section Header */}
      <div className="flex flex-col sm:flex-row justify-between items-center mb-8">
        <div>
          <div className="p-3 rounded-xl bg-amber-100/20 text-amber-400 border border-amber-500/30">
            <MoreHorizontal className="w-5 h-5" />
          </div>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-slate-100">
            Frequently Asked Questions
          </h2>
          <p className="mt-2 text-slate-400">
            Quick answers to dining essentials and specials.
          </p>
        </div>
        <div className="mt-6 sm:mt-0">
          <button
            type="button"
            className="inline-flex items-center justify-center px-4 py-2 text-sm font-medium text-slate-300 bg-white/10 border border-white/20 rounded-xl hover:bg-white/20 active:scale-95 transition-all duration-200"
          >
            Ask a Question <ChevronRight className="ml-2 w-3 h-3" />
          </button>
        </div>
      </div>

      {/* Accordion Panel */}
      <div className="space-y-4">
        {mockFAQs.map((faq) => {
          const isActive = active.includes(faq.id);
          return (
            <div key={faq.id} className="group relative border border-white/10 rounded-xl bg-white/5 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-white/20">
              <div className="flex justify-between items-start mb-4">
                <div className="space-y-1">
                  <h3 className="font-semibold text-slate-200 text-lg">{faq.title}</h3>
                  <p className="text-slate-400 text-sm">{faq.content}</p>
                </div>
                <button
                  type="button"
                  className="p-2 rounded-lg bg-white/5 border border-white/10 text-slate-400 transition-colors duration-200 group-hover:text-amber-400"
                  onClick={() => toggle(faq.id)}
                >
                  {isActive ? <ChevronDown className="w-4 h-4" /> : <ChevronDown className="w-4 h-4 text-amber-400" />}
                </button>
              </div>
              {isActive && (
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-amber-500/10 to-amber-500/0 opacity-0 group-hover:opacity-60 transition-opacity duration-300" />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

