}

import React, { useState } from 'react';
import { Calendar, Clock, CheckCircle2, MapPin, UtensilsCrossed, ChefHat, Wine, Phone, Circle as At, Sparkles, X, ArrowRight } from 'lucide-react';

const initialForm = {
  name: '',
  email: '',
  phone: '',
  date: '2024-01-14',
  time: '19:00',
  guests: 4,
  specialRequests: '',
};

const dates = [
  '2024-01-14', '2024-01-15', '2024-01-16', '2024-01-17', '2024-01-18',
  '2024-01-19', '2024-01-20', '2024-01-21', '2024-01-22', '2024-01-23',
];

export default function Reservations() {
  const [formData, setFormData] = useState(initialForm);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const validateForm = () => {
    return formData.name.trim() && formData.email.includes('@') && formData.phone.length === 10;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validateForm()) {
      alert('Please fill out the required fields correctly.');
      return;
    }

    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setIsSuccess(true);
    }, 1200);
  };

  const TimeSlot = ({ time, isOccupied = false }) => {
    return (
      <div className="group relative flex items-center gap-2 rounded-xl bg-slate-900/10 px-4 py-3 text-slate-400 transition-all duration-300 hover:bg-slate-900/20">
        {isOccupied ? (
          <div className="absolute -inset-0.5 bg-rose-500/10" />
        ) : (
          <div className="absolute -inset-0.5 bg-amber-500/10" />
        )}
        <div className="relative flex items-center gap-2">
          <Clock className="w-4 h-4 text-slate-500" />
          <span className="text-xs font-medium text-slate-300">{time}</span>
        </div>
        {isOccupied ? (
          <span className="inline-flex items-center gap-1 text-sm text-rose-300 opacity-80">
            <Sparkles className="w-3.5 h-3.5 text-rose-400" /> Full Table
          </span>
        ) : (
          <span className="inline-flex items-center gap-1 text-sm text-amber-300 opacity-80">
            <Sparkles className="w-3.5 h-3.5 text-amber-400" /> Available
          </span>
        )}
      </div>
    );
  };

  return (
    <div className="w-full max-w-7xl mx-auto py-24 sm:py-32">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-slate-100 sm:text-2xl">Book Your Table</h2>
          <p className="text-sm text-slate-400">Join us for an unforgettable dining experience at Casa Verde.</p>
        </div>
        <div className="flex flex-col sm:flex-row sm:gap-3">
          <button className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-slate-300 transition-colors hover:bg-white/10 active:text-slate-500">
            <MapPin className="w-4 h-4" /> <span>Map & Directions</span>
          </button>
          <button className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-slate-300 transition-colors hover:bg-white/10 active:text-slate-500">
            <Phone className="w-4 h-4" /> <span>Contact Us</span>
          </button>
        </div>
      </div>

      <div className="mt-12 sm:mt-16">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {dates.map((date) => (
            <div key={date} className="group relative overflow-hidden rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:bg-white/10 hover:scale-[1.01]">
              <div className="absolute -top-12 -right-12 w-32 bg-amber-500/20 backdrop-blur-xl transition-transform duration-500 group-hover:-translate-x-2 group-hover:-translate-y-2" />
              <h3 className="text-xl font-bold text-slate-100 group-hover:text-rose-400">{date}</h3>
              <div className="grid grid-cols-2 gap-4">
                {[18:00, 19:00, 20:00, 21:00, 22:00].map((time) => (
                  <TimeSlot key={time} time={time.toString()} />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-16 sm:mt-20">
        <div className="relative bg-white/5 p-8 shadow-2xl transition-all duration-300 hover:shadow-3xl">
          <div className="absolute -inset-1 bg-white/10" />
          <div className="relative rounded-2xl bg-white/10 p-6 backdrop-blur-xl border border-white/10">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="relative">
                  <label htmlFor="name" className="sr-only">Full Name</label>
                  <input
                    type="text"
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="Full Name"
                    className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                    required
                  />
                </div>
                <div className="relative">
                  <label htmlFor="email" className="sr-only">Email Address</label>
                  <input
                    type="email"
                    id="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    placeholder="example@domain.com"
                    className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                    required
                  />
                </div>
              </div>
              <div className="relative">
                <label htmlFor="phone" className="sr-only">Phone Number</label>
                <input
                  type="tel"
                  id="phone"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  placeholder="+1 (123) 456-7890"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="date" className="sr-only">Date</label>
                <input
                  type="date"
                  id="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  min="2024-01-14"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="time" className="sr-only">Time</label>
                <input
                  type="time"
                  id="time"
                  value={formData.time}
                  onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                  min="18:00"
                  max="22:00"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="guests" className="sr-only">Guests</label>
                <input
                  type="number"
                  id="guests"
                  value={formData.guests}
                  onChange={(e) => setFormData({ ...formData, guests: e.target.value })}
                  min="1"
                  max="12"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div>
                <label htmlFor="specialRequests" className="sr-only">Special Requests</label>
                <textarea
                  id="specialRequests"
                  value={formData.specialRequests}
                  onChange={(e) => setFormData({ ...formData, specialRequests: e.target.value })}
                  placeholder="Any dietary restrictions or seating preferences?"
                  rows="4"
                  className="w-full rounded-xl bg-white/5 py-3 px-4 text-slate-400 border border-white/10 placeholder:text-slate-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                />
              </div>
              <button
                type="submit"
                disabled={!validateForm() || isLoading}
                className="w-full rounded-xl bg-amber-800 py-4 text-center font-semibold text-slate-100 shadow-lg transition-all hover:shadow-2xl active:scale-95 disabled:opacity-50"
              >
                {isLoading ? 'Reserving...' : 'Reserve Table'}
              </button>
            </form>
          </div>
        </div>
      </div>

      {isSuccess && (
        <div className="mt-12 sm:mt-16">
          <div className="relative bg-white/5 p-8 shadow-2xl transition-all duration-300 hover:shadow-3xl">
            <div className="absolute -inset-1 bg-white/10" />
            <div className="relative rounded-2xl bg-white/10 p-6 backdrop-blur-xl border border-white/10 flex flex-col items-center gap-4">
              <CheckCircle2 className="w-12 h-12 text-emerald-400" />
              <h3 className="text-xl font-bold text-slate-100">Reservation Confirmed!</h3>
              <p className="text-sm text-slate-400">We've saved your seat. See you at the table!</p>
              <button
                onClick={() => setIsSuccess(false)}
                className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-slate-300 transition-colors hover:bg-white/10 active:text-slate-500"
              >
                <ArrowRight className="w-4 h-4" /> Continue Dining
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
